changeSet.sql:
INSERT INTO corretora(id,codigo,nome,ativa,legada,usuario_id,mercado)
SELECT nextval('seq_corretora'), c.codigo || '_' || CAST(p.usuario_id AS VARCHAR(20)), c.nome, false, true, p.usuario_id, 'BR'
FROM (SELECT DISTINCT usuario_id,corretora_id FROM transacao) p JOIN corretora c ON c.id=p.corretora_id;
UPDATE transacao SET corretora_id=(
  SELECT nova.id FROM corretora antiga JOIN corretora nova
  ON nova.codigo=antiga.codigo || '_' || CAST(transacao.usuario_id AS VARCHAR(20))
  AND nova.usuario_id=transacao.usuario_id WHERE antiga.id=transacao.corretora_id
);
UPDATE corretora SET ativa=false, legada=true WHERE usuario_id IS NULL;
